-- Aquagram — 0037: ilk lokalite / varyete / ticari ad kayıtları (23 tür, 121 kayıt)
-- ve ayrı tür sayfası olarak duran üç formun ana türe taşınması.

-- 1) Ayrı sayfadaki formlar ana türün altına taşınır, eski adresler yönlendirilir
insert into public.species_forms (species_id, name, kind, origin, note, aliases, images, position)
select s.id, v.name, v.kind, v.origin, v.note, v.aliases, v.images, 0
from (values
 ('altolamprologus-compressiceps','Sumbu Shell','lokalite','Zambiya kıyısı, Sumbu çevresi (gölün güneyi)',$t$Diğer compressiceps formlarından belirgin şekilde küçük kalır ve boş salyangoz kabuklarını sığınak olarak kullanır. Kompakt boyuna rağmen tipik Altolamprologus avcı karakterini korur. Bazı kaynaklar bu formun henüz tanımlanmamış ayrı bir tür olabileceğini belirtir.$t$, array['Sumbu Dwarf','Compressiceps Sumbu','Altolamprologus Sumbu'], array['https://aquagram.com.tr/media/tur/altolamprologus-compressiceps-sumbu-shell-1.webp','https://aquagram.com.tr/media/tur/altolamprologus-compressiceps-sumbu-shell-2.webp']),
 ('rocio-octofasciata','Electric Blue','varyete','Akvaryum üretimi',$t$Jack Dempsey'nin seçilimle yaygınlaşmış parlak mavi formu. Standart forma göre daha küçük kalabildiği ve daha hassas olabildiği bildirilir; stabil su koşulları önemlidir.$t$, array['Electric Blue Jack Dempsey','EBJD','Blue Dempsey'], array[]::text[]),
 ('tanichthys-albonubes','Gold','varyete','Akvaryum üretimi',$t$White Cloud Mountain Minnow'un altın renkli akvaryum formu. Bakımı türle aynıdır: serin, temiz ve oksijenli su.$t$, array['Altın White Cloud','Gold White Cloud','Golden Mountain Minnow'], array[]::text[])
) as v(slug, name, kind, origin, note, aliases, images)
join public.species s on s.slug::text = v.slug
on conflict (species_id, name) do nothing;
insert into public.species_redirects (old_slug, new_slug, form_name) values
 ('altolamprologus-compressiceps-sumbu-shell','altolamprologus-compressiceps','Sumbu Shell'),
 ('rocio-octofasciata-electric-blue-jack-dempsey','rocio-octofasciata','Electric Blue'),
 ('tanichthys-albonubes-gold','tanichthys-albonubes','Gold')
on conflict (old_slug) do nothing;
update public.species set status = 'draft' where slug in ('altolamprologus-compressiceps-sumbu-shell','rocio-octofasciata-electric-blue-jack-dempsey','tanichthys-albonubes-gold');

